        content='# ==========================\n# History\n# ==========================\n.history/\n\n# ARCH-0V finding B-1 — database dumps and generated SQL must never be tracked.\n# backup_pre_alignment.sql was a readable pg_dump in a public repository\n# containing four bcrypt password hashes and three real email addresses.\n# Gate 0V-G6 enforces this; these patterns stop it happening by accident.\n*.dump\n*.backup\n*.bak\nbackup_*.sql\nexpand.sql\ncontract.sql\nflowpilot-*.sql\n\n# Environment files\n.env\n.env.*\n!.env.example\n!.env.*.example\nbackend/.env.production\nbackend/.env.production.*\n# Environment files - never commit credentials\n\n# Local development runtime files\n.dev/\n\n# ARCH-40 apply backup\n**/.arch40_apply_backup/\n\n# ARCH41-S1:gitignore. ARCH-41 apply backups, and the encrypted database\n# backups the backup floor writes. Encrypted or not, a database backup has no\n# place in a public repository (see ARCH-0V finding B-1 above).\n**/.arch41_apply_backup/\n.flowpilot_backups/\n**/.flowpilot_backups/\n*.fpbk\n*.fpbk.partial\n\n',
