        content='#!/usr/bin/env bash\nset -uo pipefail\n\nCONFIG_FILE="${FLOWPILOT_SWEEPER_ENV:-/etc/flowpilot/sweepers.env}"\n[[ -r "${CONFIG_FILE}" ]] && source "${CONFIG_FILE}"\n\nFLOWPILOT_ROOT="${FLOWPILOT_ROOT:-/srv/flowpilot}"\nFLOWPILOT_VENV="${FLOWPILOT_VENV:-${FLOWPILOT_ROOT}/venv}"\nFLOWPILOT_LOG_DIR="${FLOWPILOT_LOG_DIR:-/var/log/flowpilot}"\nTEXTFILE_DIR="${TEXTFILE_DIR:-/var/lib/node_exporter/textfile_collector}"\nLOCK_DIR="${LOCK_DIR:-/var/lock/flowpilot}"\n\nif [[ $# -lt 1 ]]; then\n    echo "usage: $(basename "$0") <arch07|identity|invitations|arch09|compliance|backup|restore-drill> [args...]" >&2\n    exit 64\nfi\n\nNAME="$1"; shift\n\ncase "${NAME}" in\n    arch07)      SCRIPT="scripts/sweep_arch07.py"      ; HEARTBEAT="${HEARTBEAT_UUID_ARCH07:-}"      ;;\n    identity)    SCRIPT="scripts/sweep_identity.py"    ; HEARTBEAT="${HEARTBEAT_UUID_IDENTITY:-}"    ;;\n    invitations) SCRIPT="scripts/sweep_invitations.py" ; HEARTBEAT="${HEARTBEAT_UUID_INVITATIONS:-}" ;;\n    arch09)      SCRIPT="scripts/sweep_arch09.py"      ; HEARTBEAT="${HEARTBEAT_UUID_ARCH09:-}"      ;;\n    compliance)  SCRIPT="scripts/sweep_compliance.py"  ; HEARTBEAT="${HEARTBEAT_UUID_COMPLIANCE:-}" ;;\n    # ARCH41-S1:sweep-backup. The backup floor and its weekly restore drill\n    # get the same lock, log, heartbeat and textfile metric as every sweeper.\n    backup)        SCRIPT="scripts/backup_floor.py"  ; HEARTBEAT="${HEARTBEAT_UUID_BACKUP:-}"        ;;\n    restore-drill) SCRIPT="scripts/restore_drill.py" ; HEARTBEAT="${HEARTBEAT_UUID_RESTORE_DRILL:-}" ;;\n    *)\n        echo "unknown sweeper: ${NAME}" >&2\n        exit 64\n        ;;\nesac\n\nmkdir -p "${FLOWPILOT_LOG_DIR}" "${LOCK_DIR}"\nLOG_FILE="${FLOWPILOT_LOG_DIR}/sweep_${NAME}.log"\nLOCK_FILE="${LOCK_DIR}/sweep_${NAME}.lock"\n\nSTARTED_AT="$(date -u +%s)"\n\n{\n    echo "=== $(date -u +%FT%TZ) | sweep ${NAME} | args: $* ==="\n} >> "${LOG_FILE}"\n\nMODULE="${SCRIPT%.py}"\nMODULE="${MODULE//\\//.}"\n\ncd "${FLOWPILOT_ROOT}/backend" || {\n    echo "SWEEP_FAILED | ${NAME} | cannot cd to ${FLOWPILOT_ROOT}/backend" >> "${LOG_FILE}"\n    exit 1\n}\n\nflock -w 0 "${LOCK_FILE}" \\\n    env SERVICE_ROLE=sweeper \\\n    "${FLOWPILOT_VENV}/bin/python" -m "${MODULE}" "$@" \\\n    >> "${LOG_FILE}" 2>&1\nSTATUS=$?\n\nFINISHED_AT="$(date -u +%s)"\nDURATION=$(( FINISHED_AT - STARTED_AT ))\n\nOUTCOME="fail"\ncase "${STATUS}" in\n    0)\n        OUTCOME="ok"\n        ;;\n    3)\n        if [[ "${NAME}" == "invitations" ]]; then\n            OUTCOME="ok"\n            echo "SWEEP_SKIPPED | ${NAME} | advisory lock held elsewhere" >> "${LOG_FILE}"\n        fi\n        ;;\n    2)\n        echo "SWEEP_BAD_ARGS | ${NAME} | argparse rejected: $*" >> "${LOG_FILE}"\n        ;;\nesac\n\nif [[ -d "${TEXTFILE_DIR}" ]]; then\n    TMP="$(mktemp "${TEXTFILE_DIR}/flowpilot_sweeper_${NAME}.XXXXXX")"\n    {\n        echo "# HELP flowpilot_sweeper_last_run_timestamp_seconds Unix time of the last completed run."\n        echo "# TYPE flowpilot_sweeper_last_run_timestamp_seconds gauge"\n        echo "flowpilot_sweeper_last_run_timestamp_seconds{sweeper=\\"${NAME}\\"} ${FINISHED_AT}"\n        echo "# HELP flowpilot_sweeper_last_exit_code Exit status of the last run."\n        echo "# TYPE flowpilot_sweeper_last_exit_code gauge"\n        echo "flowpilot_sweeper_last_exit_code{sweeper=\\"${NAME}\\"} ${STATUS}"\n        echo "# HELP flowpilot_sweeper_last_duration_seconds Wall-clock duration of the last run."\n        echo "# TYPE flowpilot_sweeper_last_duration_seconds gauge"\n        echo "flowpilot_sweeper_last_duration_seconds{sweeper=\\"${NAME}\\"} ${DURATION}"\n        if [[ "${OUTCOME}" == "ok" ]]; then\n            echo "# HELP flowpilot_sweeper_last_success_timestamp_seconds Unix time of the last successful run."\n            echo "# TYPE flowpilot_sweeper_last_success_timestamp_seconds gauge"\n            echo "flowpilot_sweeper_last_success_timestamp_seconds{sweeper=\\"${NAME}\\"} ${FINISHED_AT}"\n        elif [[ -f "${TEXTFILE_DIR}/flowpilot_sweeper_${NAME}.prom" ]]; then\n            grep \'^flowpilot_sweeper_last_success_timestamp_seconds\' \\\n                "${TEXTFILE_DIR}/flowpilot_sweeper_${NAME}.prom" 2>/dev/null || true\n        fi\n    } > "${TMP}"\n    chmod 644 "${TMP}"\n    mv "${TMP}" "${TEXTFILE_DIR}/flowpilot_sweeper_${NAME}.prom"\nfi\n\nif [[ -n "${HEARTBEAT_BASE:-}" && -n "${HEARTBEAT}" ]]; then\n    if [[ "${OUTCOME}" == "ok" ]]; then\n        URL="${HEARTBEAT_BASE}/${HEARTBEAT}"\n    else\n        URL="${HEARTBEAT_BASE}/${HEARTBEAT}/fail"\n    fi\n    curl -fsS -m 10 --retry 3 --retry-delay 2 -o /dev/null "${URL}" \\\n        || echo "HEARTBEAT_PING_FAILED | ${NAME} | ${URL}" >> "${LOG_FILE}"\nfi\n\necho "SWEEP_WRAPPER_DONE | ${NAME} | status=${STATUS} outcome=${OUTCOME} duration=${DURATION}s" \\\n    >> "${LOG_FILE}"\n\nexit "${STATUS}"',
